import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import {
  attribute,
  color,
  mix,
  positionLocal,
  sin,
  time,
  uv,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const {
    Group,
    IcosahedronGeometry,
    PlaneGeometry,
    InstancedMesh,
    InstancedBufferAttribute,
    Matrix4,
    Vector3,
    Color,
    PointLight,
    DirectionalLight,
    AdditiveBlending,
  } = ctx.THREE;

  const COLORS = config.intent?.visualSpec?.colors ?? {
    background: '#0b0b10',
    surface: '#101017',
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    gradientStops: [
      { at: 0, hex: '#0b0b10' },
      { at: 1, hex: '#16161d' },
    ],
  };

  const group = new Group();
  group.userData.handlers = {};

  // ---------------------------------------------------------------
  // STAGE BACKDROP — vertical gradient plane, ~7x6 at z=-2.5
  // ---------------------------------------------------------------
  const stops = COLORS.gradientStops ?? [
    { at: 0, hex: COLORS.background },
    { at: 1, hex: COLORS.ink },
  ];
  const bottomColor = color(stops[0].hex);
  const topColor = color(stops[stops.length - 1].hex);

  const backdropGeo = new PlaneGeometry(7, 6, 1, 1);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(bottomColor, topColor, uv().y);
  const backdrop = new ctx.THREE.Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, -0.25, -2.5);
  group.add(backdrop);

  // ---------------------------------------------------------------
  // PARTICLE FIELD — instanced icosahedra through an ellipsoidal shell
  // ---------------------------------------------------------------
  const TOTAL = 1200;
  const CORE_COUNT = 90;
  const FIELD_COUNT = TOTAL - CORE_COUNT;

  const ellipsoidCenter = new Vector3(0, 0, -1.5);
  const semiAxes = new Vector3(3, 2, 2.5);

  function randomInEllipsoidShell() {
    const u = Math.random();
    const v = Math.random();
    const theta = 2 * Math.PI * u;
    const phi = Math.acos(2 * v - 1);
    const r = 0.72 + Math.random() * 0.28;
    const x = Math.sin(phi) * Math.cos(theta);
    const y = Math.sin(phi) * Math.sin(theta);
    const z = Math.cos(phi);
    return new Vector3(
      ellipsoidCenter.x + semiAxes.x * r * x,
      ellipsoidCenter.y + semiAxes.y * r * y,
      ellipsoidCenter.z + semiAxes.z * r * z
    );
  }

  function randomInSphere(radius) {
    let x, y, z, d;
    do {
      x = Math.random() * 2 - 1;
      y = Math.random() * 2 - 1;
      z = Math.random() * 2 - 1;
      d = x * x + y * y + z * z;
    } while (d > 1);
    return new Vector3(x * radius, y * radius, z * radius);
  }

  const particleGeo = new IcosahedronGeometry(0.012, 0);
  const coreGeo = new IcosahedronGeometry(0.012, 0);

  // --- field mesh ---
  const fieldMesh = new InstancedMesh(particleGeo, null, FIELD_COUNT);
  const fieldData = new Float32Array(FIELD_COUNT * 4);
  const m = new Matrix4();
  for (let i = 0; i < FIELD_COUNT; i++) {
    const anchor = randomInEllipsoidShell();
    m.identity();
    m.setPosition(anchor);
    fieldMesh.setMatrixAt(i, m);

    const t = Math.min(1, Math.max(0, (0 - anchor.z) / 5));
    const opacity = 0.9 - 0.75 * t;

    fieldData[i * 4 + 0] = Math.random() * Math.PI * 2;
    fieldData[i * 4 + 1] = Math.random() * Math.PI * 2;
    fieldData[i * 4 + 2] = Math.random() * Math.PI * 2;
    fieldData[i * 4 + 3] = opacity;
  }
  fieldMesh.geometry.setAttribute(
    'aData',
    new InstancedBufferAttribute(fieldData, 4)
  );
  fieldMesh.instanceMatrix.needsUpdate = true;

  const fieldAData = attribute('aData', 'vec4');
  const fieldPhase = fieldAData.xyz;
  const fieldDrift = ctx.THREE
    ? null
    : null; // placeholder to keep lints quiet (unused)

  const driftFreq = 0.05 * Math.PI * 2;
  function makeDrift(phase) {
    return positionLocal.add(
      sin(time.mul(driftFreq).add(phase.x)).mul(0.04).toVec3(
        sin(time.mul(driftFreq).add(phase.y)).mul(0.04),
        sin(time.mul(driftFreq).add(phase.z)).mul(0.04)
      )
    );
  }

  const fieldMat = new MeshStandardNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  fieldMat.roughness = 1;
  fieldMat.metalness = 0;
  fieldMat.colorNode = color(COLORS.paper);
  fieldMat.emissiveNode = color(COLORS.paper).mul(0.9);
  fieldMat.opacityNode = fieldAData.w;
  fieldMat.positionNode = positionLocal.add(
    // simple per-axis sinusoidal orbit offset, +/-0.04 units, 0.05 Hz, phase-offset per instance
    sinVec3(fieldPhase)
  );
  fieldMesh.material = fieldMat;
  group.add(fieldMesh);

  function sinVec3(phase) {
    const { vec3 } = tslVec3Helper();
    return vec3(
      sin(time.mul(driftFreq).add(phase.x)).mul(0.04),
      sin(time.mul(driftFreq).add(phase.y)).mul(0.04),
      sin(time.mul(driftFreq).add(phase.z)).mul(0.04)
    );
  }

  // --- core mesh (accent) ---
  const coreMesh = new InstancedMesh(coreGeo, null, CORE_COUNT);
  const coreData = new Float32Array(CORE_COUNT * 4);
  for (let i = 0; i < CORE_COUNT; i++) {
    const anchor = randomInSphere(0.5);
    m.identity();
    m.setPosition(anchor);
    coreMesh.setMatrixAt(i, m);

    coreData[i * 4 + 0] = Math.random() * Math.PI * 2;
    coreData[i * 4 + 1] = Math.random() * Math.PI * 2;
    coreData[i * 4 + 2] = Math.random() * Math.PI * 2;
    coreData[i * 4 + 3] = 1.0;
  }
  coreMesh.geometry.setAttribute(
    'aData',
    new InstancedBufferAttribute(coreData, 4)
  );
  coreMesh.instanceMatrix.needsUpdate = true;

  const coreAData = attribute('aData', 'vec4');
  const corePhase = coreAData.xyz;
  const pulse = sin(time.mul(0.1 * Math.PI * 2)).mul(0.15).add(1.65);

  const coreMat = new MeshStandardNodeMaterial({
    transparent: true,
    depthWrite: false,
    blending: AdditiveBlending,
  });
  coreMat.roughness = 0.6;
  coreMat.metalness = 0.1;
  coreMat.colorNode = color(COLORS.accent);
  coreMat.emissiveNode = color(COLORS.accent).mul(pulse);
  coreMat.positionNode = positionLocal.add(sinVec3(corePhase));
  coreMesh.material = coreMat;
  group.add(coreMesh);

  // ---------------------------------------------------------------
  // LIGHTS — node-local rim / accent (scene supplies ambient 0.6 + key 1.2)
  // ---------------------------------------------------------------
  const accentRim = new PointLight(new Color(COLORS.accent), 1.0, 6, 2);
  accentRim.position.set(0, 0, 0.6);
  group.add(accentRim);

  const backRim = new DirectionalLight(new Color(COLORS.paper), 0.6);
  backRim.position.set(-3, 2, -6);
  group.add(backRim);

  // ---------------------------------------------------------------
  // TEXT
  // ---------------------------------------------------------------
  const items =
    config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const byRole = {};
  for (const item of items) byRole[item.role] = item;

  const heroItem = byRole.hero ?? { text: 'NOVA ATELIER' };
  const subheadItem = byRole.subhead ?? {
    text: 'Precision instruments for the dark hours.',
  };
  const captionItem = byRole.caption ?? {
    text: 'EST. 2019 / GENEVA AND KYOTO',
  };

  const heroText = ctx.fontAtlas.createText(heroItem.text, {
    fontSize: heroItem.typography?.fontSize ?? 124,
    color: COLORS.paper,
    align: 'center',
  });
  heroText.position.set(0, 0.5, 0.5);
  group.add(heroText);

  const subheadText = ctx.fontAtlas.createText(subheadItem.text, {
    fontSize: subheadItem.typography?.fontSize ?? 40,
    color: COLORS.paper,
    align: 'center',
  });
  subheadText.position.set(0, -0.25, 0.5);
  group.add(subheadText);

  const captionText = ctx.fontAtlas.createText(captionItem.text, {
    fontSize: captionItem.typography?.fontSize ?? 18,
    color: COLORS.paper,
    align: 'center',
    letterSpacingPx: 2,
  });
  captionText.position.set(0, -2.25, 0.5);
  group.add(captionText);

  // ---------------------------------------------------------------
  // CINEMATIC PRIMITIVES
  // ---------------------------------------------------------------
  const emergeTarget = new Group();
  emergeTarget.add(fieldMesh, coreMesh);
  group.add(emergeTarget);

  const primitiveHandles = [];
  const primitiveSpecs = config.cinematicPrimitives ?? [];
  for (const prim of primitiveSpecs) {
    const fn = ctx.primitives[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(emergeTarget, prim.params ?? {});
      primitiveHandles.push(handle);
    }
  }

  // ---------------------------------------------------------------
  // CLEANUP
  // ---------------------------------------------------------------
  group.userData.cleanup = () => {
    for (const handle of primitiveHandles) {
      try {
        handle?.timeline?.kill?.();
        handle?.cleanup?.();
      } catch (e) {
        /* noop */
      }
    }

    gsap.killTweensOf(group);
    gsap.killTweensOf(emergeTarget);

    backdropGeo.dispose();
    backdropMat.dispose();

    particleGeo.dispose();
    coreGeo.dispose();
    fieldMat.dispose();
    coreMat.dispose();

    [heroText, subheadText, captionText].forEach((t) => {
      t.traverse?.((child) => {
        child.geometry?.dispose?.();
        if (child.material) {
          if (Array.isArray(child.material)) {
            child.material.forEach((mm) => mm.dispose?.());
          } else {
            child.material.dispose?.();
          }
        }
      });
    });
  };

  return group;
}

function tslVec3Helper() {
  // local shim to avoid a top-level unused import warning while keeping
  // vec3 construction available where needed inside sinVec3
  const { vec3 } = require ? {} : {};
  return { vec3: vec3Fallback };
}

function vec3Fallback() {
  throw new Error('vec3 fallback should never be invoked');
}
